# -*- coding: utf-8 -*-
"""patch_fiscal_v6.py — Saudi Government Finances 2026, version 6 (08/11/2026).

What changed since version 5.1 (01/10/2026) and where it lands on the page:
  • Ministry of Finance July–September report (published 03/11): Jul–Sep gap SAR 84.3 bn; Jan–Sep gap SAR 244.3 bn — equal
    to the Ministry's full-year estimate (245) with a quarter to go; oil income −23% y/y despite ~$91 Brent (fewer barrels);
    spending −4% y/y (first wartime quarter of restraint); interest +38% (9M) / +69% (Q3); debt SAR 1,773.6 bn end-Sep;
    reserve at SAMA SAR 399.5 bn. → sections 02, 03 (charts A/B/C), 04, 05 (chart F), 06.
    Figures as reported from the Ministry's report by Arab News (03/11) and Asharq Al-Awsat (04/11), cross-checked.
  • Oil: Brent averaged ~$108 in October, peak $117.6 (30/10), ~$102 on 06/11; OPEC+ held targets 04/10 and 01/11, next
    29/11; exports back near pre-war in October (6.5–7.9 mb/d by tracker; Yanbu ~2.5); Aramco Q3 (03/11). → 02, 05 (chart E).
  • War: Yemeni government forces retook the Dhubab–Mokha coast 5–6/10 (strait contested, Houthi embargo on Saudi ships
    still declared); Houthi missile/drone claims against Ras Tanura (fire contained 27/10), Rabigh, Abqaiq, Riyadh; US
    limited strikes on Iran 6–7/11 with talks continuing. → 01, 06, 08.
  • Macro: IMF (13/10) −3.3% 2026 / +7.9% 2027; GASTAT Q3 flash −3.8% y/y; Kamco Q3 construction awards −45%. → 04.
  • EH year-end range re-based from 245–280 to 300–350 (EH arithmetic, stated as such). → 01, 02, 05, 06.
Arabic: every new or changed English block gets an entry in the full-mode dictionary (embedded <script id="ehArFull"> and
saudi_fiscal_monitor_2026.ar.json, rewritten from one dict); new chart labels go into eh-ar-dashboard.js D.lbl.
The legacy #ehArView (hidden in full mode) only gets its version line changed.

Run once:  python3 pipeline/patch_fiscal_v6.py
"""
import os, sys, json, re
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
from patchlib import load, rep, rep_re, FILES, FAILURES, write_change_table, _log

HUB = os.path.join(HERE, '..', 'hub')
P = os.path.join(HUB, 'saudi_fiscal_monitor_2026.html')
J = os.path.join(HUB, 'saudi_fiscal_monitor_2026.ar.json')
A = os.path.join(HUB, 'eh-ar-dashboard.js')
if 'version 6' in open(P, encoding='utf-8').read():
    sys.exit('Already applied — nothing to do.')
load(P, 'fisc'); load(A, 'arjs')
K = 'fisc'

# ---------------------------------------------------------------- Arabic dictionary (embedded + .ar.json), as in patch_audit_macro_fisc.py
m = re.search(r'(<script type="application/json" id="ehArFull">)(.*?)(</script>)', FILES[K], re.S)
raw = m.group(2); D = json.loads(raw)
emb_fmt = lambda d: json.dumps(d, ensure_ascii=False).replace('</', '<\\/')
assert emb_fmt(D) == raw, 'embedded dictionary format changed — refusing to rewrite'
jtxt = open(J, encoding='utf-8').read(); assert json.loads(jtxt) == D, 'ar.json and embedded dictionary differ'
assert json.dumps(D, ensure_ascii=False, indent=0) == jtxt, 'ar.json format changed'
normH = lambda h: re.sub(r'\s+', ' ', h).strip()

def dict_set(en, ar, note):
    """Add (or overwrite) the Arabic for one leaf block, keyed by its whitespace-normalised innerHTML."""
    k = normH(en); D[k] = ar; _log(K, 'dict', k, ar, 'ar', note, 1, True)
def dict_rename(old, new, ar, note):
    k0, k1 = normH(old), normH(new); ok = k0 in D
    if ok: D.pop(k0)
    D[k1] = ar; _log(K, 'dict', k0, k1 + ' => ' + ar, 'ar', note, int(ok), ok)
def leaf(h):
    """The dictionary keys on a leaf element's innerHTML: drop one outer div/p/span wrapper and a trailing close tag."""
    h = h.strip()
    if h.startswith('<span class="vtag">'): return h[len('<span class="vtag">'):-len('</span>')]
    h = re.sub(r'^<(div|p)\b[^>]*>', '', h); h = re.sub(r'</(div|p)>$', '', h.strip()); return h
def R(old, new, note, ar=None, count=None):
    """Replace an English block; when `ar` is given, move its dictionary entry to the new text.
    A plain-text block also appears verbatim as a key inside the embedded dictionary JSON, so the count may be 2;
    the dictionary is rewritten wholesale at the end, so replacing it there too is harmless."""
    n = FILES[K].count(old) if count is None else count
    rep(K, old, new, 'v6', note, count=max(n, 1))
    if ar is not None: dict_rename(leaf(old), leaf(new), ar, 'AR: ' + note)

